544  bool PLY::ElementInstanceList::ParseInstanceList(
   545          IOStreamBuffer<char> &streamBuffer,
   546          std::vector<char> &buffer,
   547          const PLY::Element *pcElement,
   548          PLY::ElementInstanceList *p_pcOut,
   549          PLYImporter *loader) {
   550      ai_assert(nullptr != pcElement);
   551
   552      // parse all elements
   553      if (EEST_INVALID == pcElement->eSemantic || pcElement->alProperties.empty()) {
   554          // if the element has an unknown semantic we can skip all lines
   555          // However, there could be comments
   556          for (unsigned int i = 0; i < pcElement->NumOccur; ++i) {
   557              PLY::DOM::SkipComments(buffer);
   558              PLY::DOM::SkipLine(buffer);
   559              streamBuffer.getNextLine(buffer);
   560          }
   561      } else {
   562          const char *pCur = (const char *)&buffer[0];
   563          // be sure to have enough storage
   564          for (unsigned int i = 0; i < pcElement->NumOccur; ++i) {
   565              if (p_pcOut)
   566                  PLY::ElementInstance::ParseInstance(pCur, pcElement, &p_pcOut->alInstances[i]);
   567              else {
   568                  ElementInstance elt;
   569                  PLY::ElementInstance::ParseInstance(pCur, pcElement, &elt);
   570
   571                  // Create vertex or face
   572                  if (pcElement->eSemantic == EEST_Vertex) {
   573                      //call loader instance from here
   574                      loader->LoadVertex(pcElement, &elt, i);
   575                  } else if (pcElement->eSemantic == EEST_Face) {
   576                      //call loader instance from here
   577                      loader->LoadFace(pcElement, &elt, i);
   578                  } else if (pcElement->eSemantic == EEST_TriStrip) {
   579                      //call loader instance from here
   580                      loader->LoadFace(pcElement, &elt, i);
   581                  }
   582              }
   583
   584              streamBuffer.getNextLine(buffer);
   585              pCur = (buffer.empty()) ? nullptr : (const char *)&buffer[0];
   586          }
   587      }
   588      return true;
   589  }
