   592  bool PLY::ElementInstanceList::ParseInstanceListBinary(
   593          IOStreamBuffer<char> &streamBuffer,
   594          std::vector<char> &buffer,
   595          const char *&pCur,
   596          unsigned int &bufferSize,
   597          const PLY::Element *pcElement,
   598          PLY::ElementInstanceList *p_pcOut,
   599          PLYImporter *loader,
   600          bool p_bBE /* = false */) {
   601      ai_assert(nullptr != pcElement);
   602
   603      // we can add special handling code for unknown element semantics since
   604      // we can't skip it as a whole block (we don't know its exact size
   605      // due to the fact that lists could be contained in the property list
   606      // of the unknown element)
   607      for (unsigned int i = 0; i < pcElement->NumOccur; ++i) {
   608          if (p_pcOut)
   609              PLY::ElementInstance::ParseInstanceBinary(streamBuffer, buffer, pCur, bufferSize, pcElement, &p_pcOut->alInstances[i], p_bBE);
   610          else {
   611              ElementInstance elt;
   612              PLY::ElementInstance::ParseInstanceBinary(streamBuffer, buffer, pCur, bufferSize, pcElement, &elt, p_bBE);
   613
   614              // Create vertex or face
   615              if (pcElement->eSemantic == EEST_Vertex) {
   616                  //call loader instance from here
   617                  loader->LoadVertex(pcElement, &elt, i);
   618              } else if (pcElement->eSemantic == EEST_Face) {
   619                  //call loader instance from here
   620                  loader->LoadFace(pcElement, &elt, i);
   621              } else if (pcElement->eSemantic == EEST_TriStrip) {
   622                  //call loader instance from here
   623                  loader->LoadFace(pcElement, &elt, i);
   624              }
   625          }
   626      }
   627      return true;
   628  }
