   631  bool PLY::ElementInstance::ParseInstance(const char *&pCur,
   632          const PLY::Element *pcElement,
   633          PLY::ElementInstance *p_pcOut) {
   634      ai_assert(nullptr != pcElement);
   635      ai_assert(nullptr != p_pcOut);
   636
   637      // allocate enough storage
   638      p_pcOut->alProperties.resize(pcElement->alProperties.size());
   639
   640      std::vector<PLY::PropertyInstance>::iterator i = p_pcOut->alProperties.begin();
   641      std::vector<PLY::Property>::const_iterator a = pcElement->alProperties.begin();
   642      for (; i != p_pcOut->alProperties.end(); ++i, ++a) {
   643          if (!(PLY::PropertyInstance::ParseInstance(pCur, &(*a), &(*i)))) {
   644              ASSIMP_LOG_WARN("Unable to parse property instance. "
   645                              "Skipping this element instance");
   646
   647              PLY::PropertyInstance::ValueUnion v = PLY::PropertyInstance::DefaultValue((*a).eType);
   648              (*i).avList.push_back(v);
   649          }
   650      }
   651      return true;
   652  }
