   683  bool PLY::PropertyInstance::ParseInstance(const char *&pCur,
   684          const PLY::Property *prop, PLY::PropertyInstance *p_pcOut) {
   685      ai_assert(nullptr != prop);
   686      ai_assert(nullptr != p_pcOut);
   687
   688      // skip spaces at the beginning
   689      if (!SkipSpaces(&pCur)) {
   690          return false;
   691      }
   692
   693      if (prop->bIsList) {
   694          // parse the number of elements in the list
   695          PLY::PropertyInstance::ValueUnion v;
   696          PLY::PropertyInstance::ParseValue(pCur, prop->eFirstType, &v);
   697
   698          // convert to unsigned int
   699          unsigned int iNum = PLY::PropertyInstance::ConvertTo<unsigned int>(v, prop->eFirstType);
   700
   701          // parse all list elements
   702          p_pcOut->avList.resize(iNum);
   703          for (unsigned int i = 0; i < iNum; ++i) {
   704              if (!SkipSpaces(&pCur))
   705                  return false;
   706
   707              PLY::PropertyInstance::ParseValue(pCur, prop->eType, &p_pcOut->avList[i]);
   708          }
   709      } else {
   710          // parse the property
   711          PLY::PropertyInstance::ValueUnion v;
   712
   713          PLY::PropertyInstance::ParseValue(pCur, prop->eType, &v);
   714          p_pcOut->avList.push_back(v);
   715      }
   716      SkipSpacesAndLineEnd(&pCur);
   717      return true;
   718  }
