   721  bool PLY::PropertyInstance::ParseInstanceBinary(IOStreamBuffer<char> &streamBuffer, std::vector<char> &buffer,
   722          const char *&pCur,
   723          unsigned int &bufferSize,
   724          const PLY::Property *prop,
   725          PLY::PropertyInstance *p_pcOut,
   726          bool p_bBE) {
   727      ai_assert(nullptr != prop);
   728      ai_assert(nullptr != p_pcOut);
   729
   730      // parse all elements
   731      if (prop->bIsList) {
   732          // parse the number of elements in the list
   733          PLY::PropertyInstance::ValueUnion v;
   734          PLY::PropertyInstance::ParseValueBinary(streamBuffer, buffer, pCur, bufferSize, prop->eFirstType, &v, p_bBE);
   735
   736          // convert to unsigned int
   737          unsigned int iNum = PLY::PropertyInstance::ConvertTo<unsigned int>(v, prop->eFirstType);
   738
   739          // parse all list elements
   740          p_pcOut->avList.resize(iNum);
   741          for (unsigned int i = 0; i < iNum; ++i) {
   742              PLY::PropertyInstance::ParseValueBinary(streamBuffer, buffer, pCur, bufferSize, prop->eType, &p_pcOut->avList[i], p_bBE);
   743          }
   744      } else {
   745          // parse the property
   746          PLY::PropertyInstance::ValueUnion v;
   747          PLY::PropertyInstance::ParseValueBinary(streamBuffer, buffer, pCur, bufferSize, prop->eType, &v, p_bBE);
   748          p_pcOut->avList.push_back(v);
   749      }
   750      return true;
   751  }
