   754  PLY::PropertyInstance::ValueUnion PLY::PropertyInstance::DefaultValue(PLY::EDataType eType) {
   755      PLY::PropertyInstance::ValueUnion out;
   756
   757      switch (eType) {
   758      case EDT_Float:
   759          out.fFloat = 0.f;
   760          return out;
   761
   762      case EDT_Double:
   763          out.fDouble = 0.;
   764          return out;
   765
   766      default:;
   767      };
   768      out.iUInt = 0;
   769      return out;
   770  }
