   773  bool PLY::PropertyInstance::ParseValue(const char *&pCur,
   774          PLY::EDataType eType,
   775          PLY::PropertyInstance::ValueUnion *out) {
   776      ai_assert(nullptr != pCur);
   777      ai_assert(nullptr != out);
   778
   779      //calc element size
   780      bool ret = true;
   780      bool ret = true;
   781      switch (eType) {
   782      case EDT_UInt:
   783      case EDT_UShort:
   784      case EDT_UChar:
   785
   786          out->iUInt = (uint32_t)strtoul10(pCur, &pCur);
   787          break;
   788
   789      case EDT_Int:
   790      case EDT_Short:
   791      case EDT_Char:
   792
   793          out->iInt = (int32_t)strtol10(pCur, &pCur);
   794          break;
   795
   796      case EDT_Float:
   797          // technically this should cast to float, but people tend to use float descriptors for double data
   798          // this is the best way to not risk losing precision on import and it doesn't hurt to do this
   799          ai_real f;
   800          pCur = fast_atoreal_move<ai_real>(pCur, f);
   801          out->fFloat = (ai_real)f;
   802          break;
   803
   804      case EDT_Double:
   805          double d;
   806          pCur = fast_atoreal_move<double>(pCur, d);
   807          out->fDouble = (double)d;
   808          break;
   809
   810      case EDT_INVALID:
   811      default:
   812          ret = false;
   813          break;
   814      }
   815
   816      return ret;
   817  }
