   820  bool PLY::PropertyInstance::ParseValueBinary(IOStreamBuffer<char> &streamBuffer,
   821          std::vector<char> &buffer,
   822          const char *&pCur,
   823          unsigned int &bufferSize,
   824          PLY::EDataType eType,
   825          PLY::PropertyInstance::ValueUnion *out,
   826          bool p_bBE) {
   827      ai_assert(nullptr != out);
   828
   829      //calc element size
   830      unsigned int lsize = 0;
   831      switch (eType) {
   832      case EDT_Char:
   833      case EDT_UChar:
   834          lsize = 1;
   835          break;
   836
   837      case EDT_UShort:
   838      case EDT_Short:
   839          lsize = 2;
   840          break;
   841
   842      case EDT_UInt:
   843      case EDT_Int:
   844      case EDT_Float:
   845          lsize = 4;
   846          break;
   847
   848      case EDT_Double:
   849          lsize = 8;
   850          break;
   851
   852      case EDT_INVALID:
   853      default:
   854          break;
   855      }
   856
   857      //read the next file block if needed
   858      if (bufferSize < lsize) {
   859          std::vector<char> nbuffer;
   860          if (streamBuffer.getNextBlock(nbuffer)) {
   861              //concat buffer contents
   862              buffer = std::vector<char>(buffer.end() - bufferSize, buffer.end());
   863              buffer.insert(buffer.end(), nbuffer.begin(), nbuffer.end());
   864              nbuffer.clear();
   865              bufferSize = static_cast<unsigned int>(buffer.size());
   866              pCur = (char *)&buffer[0];
   867          } else {
   868              throw DeadlyImportError("Invalid .ply file: File corrupted");
   869          }
   870      }
   871
   872      bool ret = true;
   873      switch (eType) {
   874      case EDT_UInt: {
   875          uint32_t t;
   876          memcpy(&t, pCur, sizeof(uint32_t));
   877          pCur += sizeof(uint32_t);
   878
   879          // Swap endianness
   880          if (p_bBE) ByteSwap::Swap(&t);
   881          out->iUInt = t;
   882          break;
   883      }
   884
   885      case EDT_UShort: {
   886          uint16_t t;
   887          memcpy(&t, pCur, sizeof(uint16_t));
   888          pCur += sizeof(uint16_t);
   889
   890          // Swap endianness
   891          if (p_bBE) ByteSwap::Swap(&t);
   892          out->iUInt = t;
   893          break;
   894      }
   895
   896      case EDT_UChar: {
   897          uint8_t t;
   898          memcpy(&t, pCur, sizeof(uint8_t));
   899          pCur += sizeof(uint8_t);
   900          out->iUInt = t;
   901          break;
   902      }
   903
   904      case EDT_Int: {
   905          int32_t t;
   906          memcpy(&t, pCur, sizeof(int32_t));
   907          pCur += sizeof(int32_t);
   908
   909          // Swap endianness
   910          if (p_bBE) ByteSwap::Swap(&t);
   911          out->iInt = t;
   912          break;
   913      }
   914
   915      case EDT_Short: {
   916          int16_t t;
   917          memcpy(&t, pCur, sizeof(int16_t));
   918          pCur += sizeof(int16_t);
   919
   920          // Swap endianness
   921          if (p_bBE) ByteSwap::Swap(&t);
   922          out->iInt = t;
   923          break;
   924      }
   925
   926      case EDT_Char: {
   927          int8_t t;
   928          memcpy(&t, pCur, sizeof(int8_t));
   929          pCur += sizeof(int8_t);
   930          out->iInt = t;
   931          break;
   932      }
   933
   934      case EDT_Float: {
   935          float t;
   936          memcpy(&t, pCur, sizeof(float));
   937          pCur += sizeof(float);
   938
   939          // Swap endianness
   940          if (p_bBE) ByteSwap::Swap(&t);
   941          out->fFloat = t;
   942          break;
   943      }
   944      case EDT_Double: {
   945          double t;
   946          memcpy(&t, pCur, sizeof(double));
   947          pCur += sizeof(double);
   948
   949          // Swap endianness
   950          if (p_bBE) ByteSwap::Swap(&t);
   951          out->fDouble = t;
   952          break;
   953      }
   954      default:
   955          ret = false;
   956      }
   957
   958      bufferSize -= lsize;
   959
   960      return ret;
   961  }
